 useEffect(()=>{const client=supabase;if(!user||!client){setFaculties([]);setSubjects([]);setQuizSets([]);return}let active=true;setBusy(true);Promise.all([client.from('facolta').select('id,nome').order('nome'),client.from('materie').select('id,nome,facolta_id,anno_corso,corso_di_laurea').order('nome'),client.from('quiz_sets').select('id,materia_id,quiz_number,status,question_count').eq('status','ready').order('quiz_number')]).then(async([f,s,q])=>{if(!active)return;if(f.error)notify(f.error.message);else setFaculties((f.data||[]) as Faculty[]);if(s.error)notify(s.error.message);else setSubjects((s.data||[]) as Subject[]);if(q.error)notify(q.error.message);else setQuizSets((q.data||[]) as QuizSet[]);setBusy(false);const [w,h,st,pr]=await Promise.all([client.functions.invoke('quiz-api',{body:{action:'wallet'}}),client.functions.invoke('quiz-api',{body:{action:'history'}}),client.functions.invoke('quiz-api',{body:{action:'streaks'}}),client.functions.invoke('quiz-api',{body:{action:'profile',mode:'read'}}),...(user.acceptedPrivacy?[client.functions.invoke('quiz-api',{body:{action:'consent',accepted:true}})]:[])]);if(!active)return;if(!w.error&&w.data)setWallet(w.data);if(!h.error&&h.data?.attempts)setHistory(h.data.attempts as Attempt[]);if(!st.error&&st.data){setStreak(st.data.streak);setAchievements(st.data.achievements||[])}if(!pr.error&&pr.data?.profile){setDisplayName(pr.data.profile.display_name||'');setLeaderboardOptIn(Boolean(pr.data.profile.leaderboard_opt_in))}});return()=>{active=false}},[user])
