 useEffect(()=>{const reset=()=>{if((window as Window & {__smlIdle?:number}).__smlIdle)window.clearTimeout((window as Window & {__smlIdle?:number}).__smlIdle);(window as Window & {__smlIdle?:number}).__smlIdle=window.setTimeout(()=>notify('Sei inattivo da 15 minuti. I progressi salvati sono al sicuro.'),900000)};const events=['pointerdown','keydown','touchstart','mousemove'];events.forEach(e=>window.addEventListener(e,reset,{passive:true}));reset();return()=>events.forEach(e=>window.removeEventListener(e,reset))},[])
